import {LEVELS,LABELS,WEIGHTS,GUIDES,parseInput,validate,summarize,prioritize,filterFindings,toggleFinding,exportData,createSample} from './model.mjs';
const paths={shield:'M12 3 3 7v6c0 5 6 8 9 10 3-2 9-5 9-10V7Z',lock:'M7 10V7a5 5 0 0 1 10 0v3M5 10h14v11H5Zm7 4v3',grid:'M3 3h7v7H3Zm11 0h7v7h-7ZM3 14h7v7H3Zm11 0h7v7h-7Z',radar:'M20 12a8 8 0 1 1-8-8m0 4a4 4 0 1 0 4 4m-4 0 9-9m-6 0h6v6',layers:'m12 3 10 5-10 5L2 8Zm-10 9 10 5 10-5M2 17l10 5 10-5',book:'M12 5c-3-2-7-2-10-1v15c3-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-1-10 1Zm0 0v15',chevrons:'m8 8 4-4 4 4m-8 8 4 4 4-4','shield-check':'M12 3 3 7v6c0 5 6 8 9 10 3-2 9-5 9-10V7Zm-4 9 3 3 5-6',plus:'M12 5v14M5 12h14',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18','file-check':'M14 2H5v20h14V7Zm0 0v5h5M8 15l3 3 5-6',refresh:'M20 7a8 8 0 0 0-13-3L3 8m0-5v5h5M4 17a8 8 0 0 0 13 3l4-4m0 5v-5h-5',info:'M12 11v6m0-10v.1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',trending:'m3 17 6-6 4 4 8-10m-6 0h6v6','check-circle':'m7 12 3 3 7-7M22 12a10 10 0 1 1-4-8',alert:'m12 3 10 18H2Zm0 6v5m0 3v.1','arrow-right':'M4 12h16m-6-6 6 6-6 6',sparkles:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5ZM20 2v4m-2-2h4',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',search:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0m-2 5 6 6','chevron-right':'m9 5 7 7-7 7',external:'M14 3h7v7m-1-6L10 14M10 3H3v18h18v-7',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',x:'m6 6 12 12M6 18 18 6',upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5','arrow-up-right':'M6 18 18 6M6 6h12v12',check:'m4 12 5 5L20 6',undo:'M9 4 4 9l5 5M4 9h10a6 6 0 0 1 0 12'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.info}"/></svg>`;
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=(id)=>document.getElementById(id); const all=(s)=>[...document.querySelectorAll(s)];
const hydrate=()=>all('[data-icon]').forEach(e=>{e.innerHTML=icon(e.dataset.icon);e.removeAttribute('data-icon')});
const colors={critical:'#e45a69',high:'#ee9660',medium:'#d9b349',low:'#6c95d4',info:'#9aa4b7'};
const levelStyle=(l)=>`--level:${colors[l]}`;
const badge=(l)=>`<span class="severity-badge" style="${levelStyle(l)}"><i class="level-dot"></i>${LABELS[l]}</span>`;
const stateBadge=(f)=>`<span class="status-badge ${f.status==='resolved'?'resolved':''}">${f.status==='resolved'?'해결 완료':'미조치'}</span>`;
const STORAGE='aegis-lab-assessment-v1';
let data=createSample(),persist=false,view='dashboard',mode='manual',drafts=[{}],selected=null,confirmAction=null;
let filters={status:'all',severity:'all',query:''};
try{const saved=localStorage.getItem(STORAGE);if(saved){data=parseInput(saved);persist=true;}}catch{try{localStorage.removeItem(STORAGE)}catch{}}
try{const handoff=sessionStorage.getItem('aegis-lab-handoff-v1');if(handoff){data=parseInput(handoff);sessionStorage.removeItem('aegis-lab-handoff-v1');if(persist)localStorage.setItem(STORAGE,JSON.stringify(data));}}catch{}
let toastTimer;function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3500)}
function save(){try{if(persist)localStorage.setItem(STORAGE,JSON.stringify(data));else localStorage.removeItem(STORAGE);}catch{persist=false;$('persist-data').checked=false;toast('브라우저 저장 공간에 접근할 수 없어 임시로 보관합니다.')}}
function statusTitle(score){return score>=90?'양호':score>=70?'점검 권장':score>=40?'개선 필요':'집중 조치 필요'}
function render(){const s=summarize(data);$('target-name').textContent=data.target;$('source-name').textContent=data.source;$('sample-tag').textContent=data.isSample?'예시 데이터':'직접 입력';$('score-number').textContent=s.score;$('gauge-progress').style.strokeDashoffset=421*(1-s.score/100);$('rating').textContent=statusTitle(s.score);$('score-headline').innerHTML=s.open===0?'등록된 문제를<br>모두 해결했어요.':s.urgent>0?'중요한 위험부터<br>해결해 보세요.':'꾸준한 개선으로<br>더 안전하게.';$('score-description').innerHTML=s.open===0?'점수는 입력된 결과 기준입니다.<br>점검 범위를 계속 확인하세요.':'미조치 문제를 해결하면<br>점수가 함께 높아집니다.';$('score-gain').innerHTML=`${icon('trending')} 조치로 <b>${s.gain}점</b> 개선`;
[['open-count',s.open],['total-count',s.total],['urgent-count',s.urgent],['resolved-count',s.resolved],['nav-count',s.open]].forEach(([k,v])=>$(k).textContent=v);$('completion').textContent=`${s.completion}% 완료`;
const severityLevels=s.counts.info?[...LEVELS]:LEVELS.filter(l=>l!=='info');$('severity-bars').innerHTML=severityLevels.map(l=>`<div class="severity-row" style="${levelStyle(l)}"><i class="level-dot"></i><span class="level-name">${LABELS[l]}</span><div class="severity-track"><div class="severity-fill" style="width:${s.open?s.counts[l]/s.open*100:0}%"></div></div><b>${s.counts[l]}<span>건</span></b></div>`).join('');
const priority=prioritize(data);$('priority-list').innerHTML=priority.length?priority.slice(0,3).map((f,i)=>`<button class="priority-row" data-finding="${esc(f.id)}"><span class="priority-rank">P${i+1}</span><span class="priority-text"><b>${esc(f.title)}</b><small>${esc(f.category)} · ${esc(f.location)}</small></span>${badge(f.severity)}${icon('chevron-right')}</button>`).join(''):empty('등록된 미조치 문제가 없습니다.','입력되지 않은 영역의 위험은 별도 점검이 필요합니다.');
$('insight-copy').textContent=s.urgent?`우선 대응 ${s.urgent}건을 해결하면 ${Math.max(0,100-priority.filter(f=>!['critical','high'].includes(f.severity)).reduce((n,f)=>n+WEIGHTS[f.severity],0))-s.score}점의 개선을 기대할 수 있어요.`:s.open?`남은 ${s.open}건의 개선 항목을 차근차근 확인하세요. 모든 조치는 재검증 후 완료로 표시해 주세요.`:'입력된 문제의 조치를 모두 마쳤어요. 다음 점검에서도 안전한 흐름을 이어가세요.';$('insight-percent').textContent=`${s.completion}%`;$('insight-bar').style.width=`${s.completion}%`;
renderTables();renderPlan();$('persist-data').checked=persist;hydrate();}
function empty(title,copy){return `<div class="empty-state">${icon('check-circle')}<h3>${esc(title)}</h3><p>${esc(copy)}</p></div>`}
function tableMarkup(prefix){const s=summarize(data),rows=filterFindings(data,filters);return `<div class="table-controls"><div class="status-tabs" role="group" aria-label="문제 처리 상태">${[['all','전체',s.total],['open','미조치',s.open],['resolved','완료',s.resolved]].map(([v,l,n])=>`<button class="status-tab ${filters.status===v?'active':''}" data-status="${v}" aria-pressed="${filters.status===v}">${l}<span>${n}</span></button>`).join('')}</div><div class="table-filters"><label class="search-field">${icon('search')}<input id="${prefix}-search" data-search placeholder="문제 검색" aria-label="문제 제목, 유형, 위치 검색" value="${esc(filters.query)}"></label><select data-severity aria-label="심각도 필터"><option value="all">모든 심각도</option>${LEVELS.map(l=>`<option value="${l}" ${filters.severity===l?'selected':''}>${LABELS[l]}</option>`).join('')}</select></div></div>${rows.length?`<div class="table-scroll" tabindex="0" role="region" aria-label="발견된 문제 목록, 가로 스크롤 가능"><table><thead><tr><th scope="col">문제 이름</th><th scope="col">심각도</th><th scope="col">문제 유형</th><th scope="col">위치</th><th scope="col">상태</th><th scope="col"><span class="sr-only">상세</span></th></tr></thead><tbody>${rows.map(f=>`<tr><td><button class="finding-title" data-finding="${esc(f.id)}">${esc(f.title)}</button><span class="finding-id">${esc(f.id)}</span></td><td>${badge(f.severity)}</td><td>${esc(f.category)}</td><td><div class="location-text" title="${esc(f.location)}">${esc(f.location)}</div></td><td>${stateBadge(f)}</td><td><button class="row-arrow" data-finding="${esc(f.id)}" aria-label="${esc(f.title)} 상세 보기">${icon('chevron-right')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('조건에 맞는 문제가 없어요.','검색어 또는 필터를 바꾸면 다른 결과를 확인할 수 있습니다.')}<div class="table-bottom"><span>총 ${s.total}건 중 ${rows.length}건 표시</span><span>${icon('lock')}브라우저 내 처리</span></div>`;}
function renderTables(){const active=document.activeElement,id=active?.matches('[data-search]')?active.id:null,pos=id?active.selectionStart:null;['dashboard','findings'].forEach(p=>$(p+'-table').innerHTML=tableMarkup(p));if(id){$(id).focus();$(id).setSelectionRange(pos,pos);}}
function renderPlan(){const items=prioritize(data);$('plan-count').textContent=`남은 개선 작업 ${items.length}건`;$('plan-list').innerHTML=items.length?items.map((f,i)=>{const g=GUIDES[f.category];return `<article class="card plan-card"><div class="plan-card-top"><span class="plan-index">PRIORITY ${String(i+1).padStart(2,'0')}</span>${badge(f.severity)}</div><h3>${esc(f.title)}</h3><p>${esc(f.recommendation||g.action)}</p><span class="impact">조치 완료 시 감점 ${WEIGHTS[f.severity]}점 제외</span><button class="button secondary compact" data-finding="${esc(f.id)}">개선 가이드 확인${icon('arrow-right')}</button></article>`}).join(''):`<article class="card">${empty('등록된 개선 작업을 마쳤어요.','보고서를 내보내거나 새 진단 결과를 입력해 보세요.')}</article>`;}
const views={dashboard:['대시보드','보안 상태를, 한눈에.','발견된 위험을 이해하고, 다음 개선 작업을 결정하세요.'],findings:['발견된 문제','위험을 더 자세히 살펴보세요.','증거와 심각도를 확인하고 각 문제의 조치 상태를 관리하세요.'],plan:['개선 우선순위','다음 행동이 명확해집니다.','심각도에 따라 정리된 개선 가이드로 한 단계씩 대응하세요.'],guide:['입력 가이드','분석의 시작부터, 투명하게.','입력 형식, 점수 산정 방식과 데이터 처리 기준을 확인하세요.']};
function setView(v,scroll=true){if(!Object.hasOwn(views,v))v='dashboard';view=v;Object.keys(views).forEach(k=>$(k+'-view').hidden=k!==v);$('breadcrumb').textContent=views[v][0];$('page-title').textContent=views[v][1];$('page-subtitle').textContent=views[v][2];all('[data-view]').forEach(e=>{if(e.classList.contains('nav-item')||e.classList.contains('mobile-nav-button')){e.classList.toggle('active',e.dataset.view===v);e.setAttribute('aria-current',e.dataset.view===v?'page':'false')}});if(scroll)window.scrollTo({top:0,behavior:'instant'});}
function showDetail(id){const f=data.findings.find(f=>f.id===id);if(!f)return;selected=id;const g=GUIDES[f.category];$('detail-content').innerHTML=`<div class="drawer-head"><div><div class="detail-severity">${badge(f.severity)}<span class="detail-id">${esc(f.id)}</span></div><h2 id="detail-title" class="detail-title">${esc(f.title)}</h2><div class="detail-location">${esc(f.location)}</div></div><button class="icon-button" data-close="detail-dialog" aria-label="문제 상세 닫기">${icon('x')}</button></div><div class="drawer-content"><div class="detail-meta"><span>${esc(f.category)}</span>${stateBadge(f)}</div><section class="detail-section"><h3>${icon('info')}심각도 근거</h3><p>${esc(f.severityReason||'입력자가 지정한 심각도입니다. 영향과 재현 조건을 검토해 주세요.')}</p></section><section class="detail-section"><h3>${icon('file-check')}입력된 진단 증거</h3><p class="evidence-box">${esc(f.evidence)}</p></section><section class="detail-section"><h3>${icon('sparkles')}개선 솔루션 <span class="sample-tag">${f.recommendation?'입력된 권고':'규칙 기반 권고'}</span></h3><div class="solution-box"><p>${esc(f.recommendation||g.action)}</p></div></section><section class="detail-section"><h3>${icon('shield-check')}재검증 체크포인트</h3><p>${esc(g.check)}</p></section><a class="reference-link" href="${g.ref}" target="_blank" rel="noopener noreferrer">OWASP 개선 가이드${icon('external')}</a><div class="detail-impact">${f.status==='open'?`이 항목 조치 완료 시 감점 ${WEIGHTS[f.severity]}점이 제외됩니다.`:'완료로 표시된 항목입니다. 재발견했다면 미조치로 되돌릴 수 있습니다.'}</div><section class="detail-section"><h3>${icon('check-circle')}재검증 기록</h3>${f.status==='open'?'<label class="field">수정 내용·재검증 방법·결과 (10자 이상)<textarea id="verification-note" maxlength="4000" placeholder="예: 소유권 검증 추가 후 타 사용자 조회 403, 본인 조회 200 확인"></textarea></label><p id="verification-error" class="form-error" role="alert" hidden></p>':'<p class="evidence-box">'+esc(f.verification||'완료 상태로 입력되었지만 재검증 기록은 없습니다.')+'</p>'}</section><p class="detail-note">입력된 증거의 사실 여부와 심각도는 자동 검증하지 않습니다. 실제 환경에 맞는 담당자 검토와 허가된 재검증 후 완료 처리하세요.</p></div><div class="drawer-footer"><button class="button secondary" data-close="detail-dialog">닫기</button><button class="button ${f.status==='open'?'primary':'secondary'}" id="toggle-status">${icon(f.status==='open'?'check':'undo')}${f.status==='open'?'재검증 완료 · 해결 처리':'미조치로 되돌리기'}</button></div>`;if(!$('detail-dialog').open)$('detail-dialog').showModal();}
function collectDrafts(){drafts=drafts.map((_,i)=>Object.fromEntries(['title','severity','category','location','evidence'].map(k=>[k,$(`draft-${i}-${k}`).value])));}
function renderDrafts(){const prior=document.activeElement?.id;$('draft-findings').innerHTML=drafts.map((f,i)=>`<div class="draft-card"><div class="draft-head"><span>FINDING ${String(i+1).padStart(2,'0')}</span>${drafts.length>1?`<button type="button" data-remove-draft="${i}">삭제</button>`:''}</div><label class="field">문제 제목 *<input id="draft-${i}-title" required maxlength="200" placeholder="예: 세션 쿠키 보안 속성 누락" value="${esc(f.title||'')}"></label><div class="draft-grid"><label class="field">심각도 *<select id="draft-${i}-severity">${LEVELS.map(l=>`<option value="${l}" ${(f.severity||'medium')===l?'selected':''}>${LABELS[l]} (${l})</option>`).join('')}</select></label><label class="field">문제 유형<select id="draft-${i}-category">${Object.keys(GUIDES).map(c=>`<option ${(f.category||'기타')===c?'selected':''}>${c}</option>`).join('')}</select></label></div><label class="field">발견 위치<input id="draft-${i}-location" maxlength="300" placeholder="예: /api/login 또는 응답 헤더" value="${esc(f.location||'')}"></label><label class="field">진단 증거<textarea id="draft-${i}-evidence" maxlength="4000" placeholder="허가된 테스트에서 관찰한 결과를 적어 주세요.">${esc(f.evidence||'')}</textarea></label></div>`).join('');$('draft-count').textContent=`${drafts.length}개`;$('add-finding').disabled=drafts.length>=200;if(prior&&$(prior))$(prior).focus();}
function setMode(m){mode=m;['manual','json'].forEach(x=>{$(x+'-panel').hidden=x!==m;$(x+'-tab').classList.toggle('active',x===m);$(x+'-tab').setAttribute('aria-selected',x===m);$(x+'-tab').tabIndex=x===m?0:-1});$('input-error').hidden=true;}
function openInput(){$('input-error').hidden=true;$('input-dialog').showModal();}
function inputError(message){$('input-error').textContent=message;$('input-error').hidden=false;$('input-error').scrollIntoView({block:'nearest'});}
function analyze(){try{let next;if(mode==='manual'){if(!$('manual-form').reportValidity())return;collectDrafts();next=validate({target:$('manual-target').value,source:$('manual-source').value,findings:drafts});}else next=parseInput($('json-text').value);next.isSample=false;data=next;filters={status:'all',severity:'all',query:''};save();render();$('input-dialog').close();setView('dashboard');toast(`${data.findings.length}개 문제를 분석했습니다.`);}catch(e){inputError(e.message);}}
function download(filename,contents){const blob=new Blob([contents],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function confirm(title,copy,label,action){$('confirm-title').textContent=title;$('confirm-copy').textContent=copy;$('confirm-okay').textContent=label;confirmAction=action;$('confirm-dialog').showModal();}
const template=JSON.stringify({target:'my-staging.test',source:'허가된 수동 점검',findings:[{id:'F-001',title:'세션 쿠키 보안 속성 누락',severity:'high',category:'세션 관리',location:'응답 헤더 · Set-Cookie',evidence:'허가된 테스트에서 관찰한 결과를 기록하세요.',status:'open'}]},null,2);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){setView(b.dataset.view);return}if(b.dataset.finding){showDetail(b.dataset.finding);return}if(b.dataset.close){$(b.dataset.close).close();return}if(b.classList.contains('close-dialog')){$('input-dialog').close();return}if(b.dataset.status){filters.status=b.dataset.status;renderTables();return}if(b.dataset.mode){setMode(b.dataset.mode);return}if(b.hasAttribute('data-remove-draft')){collectDrafts();drafts.splice(Number(b.dataset.removeDraft),1);renderDrafts();return}if(b.classList.contains('export-button')){download('aegis-security-report.json',exportData(data));toast('진단 보고서를 JSON으로 내보냈습니다.');return}
switch(b.id){case'new-data':case'guide-input':openInput();break;case'add-finding':collectDrafts();if(drafts.length<200){drafts.push({});renderDrafts();$(`draft-${drafts.length-1}-title`).focus();}break;case'analyze-button':analyze();break;case'toggle-status':try{data=toggleFinding(data,selected,$('verification-note')?.value||'');save();render();showDetail(selected);toast(data.findings.find(f=>f.id===selected).status==='resolved'?'재검증 기록과 함께 해결 처리했습니다.':'미조치로 되돌렸습니다.');}catch(err){$('verification-error').textContent=err.message;$('verification-error').hidden=false;}break;case'load-sample':confirm('예시 데이터로 바꿀까요?','현재 입력 데이터와 조치 상태가 예시 결과로 대체됩니다.','불러오기',()=>{data=createSample();filters={status:'all',severity:'all',query:''};save();render();setView('dashboard');toast('가상 예시 데이터를 불러왔습니다.');});break;case'clear-data':confirm('입력 데이터를 지울까요?','저장된 진단 결과를 삭제하고 예시 화면으로 돌아갑니다.','지우기',()=>{persist=false;save();data=createSample();drafts=[{}];$('manual-form').reset();$('json-text').value='';$('json-file').value='';filters={status:'all',severity:'all',query:''};renderDrafts();render();setView('dashboard');toast('입력 데이터와 브라우저 저장본을 삭제했습니다.');});break;case'confirm-cancel':$('confirm-dialog').close();confirmAction=null;break;case'confirm-okay':$('confirm-dialog').close();if(confirmAction)confirmAction();confirmAction=null;break;case'fill-template':$('json-text').value=template;$('input-error').hidden=true;toast('JSON 형식 예시를 넣었습니다.');break;case'download-template':download('aegis-input-template.json',template);break;case'score-help':case'footer-guide':setView('guide');break;}
});
document.addEventListener('input',e=>{if(e.target.matches('[data-search]')){filters.query=e.target.value;renderTables();}});
document.addEventListener('change',e=>{if(e.target.matches('[data-severity]')){filters.severity=e.target.value;renderTables();}if(e.target.id==='persist-data'){persist=e.target.checked;save();toast(persist?'이 브라우저에 결과를 저장합니다.':'저장본을 삭제했습니다. 현재 결과는 임시로 유지합니다.');}});
$('json-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>1000000)throw new Error('파일 크기는 1MB 이하여야 합니다.');if(!file.name.toLowerCase().endsWith('.json'))throw new Error('.json 파일을 선택해 주세요.');$('json-text').value=await file.text();$('input-error').hidden=true;toast(`${file.name} 파일을 읽었습니다. 분석 버튼을 눌러 진행하세요.`);}catch(err){inputError(err.message)}finally{e.target.value=''}});
$('manual-form').addEventListener('submit',e=>{e.preventDefault();analyze()});
document.querySelector('.mode-tabs').addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();setMode((e.key==='Home'||e.key==='ArrowLeft')?'manual':'json');$(mode+'-tab').focus();}});
window.addEventListener('hashchange',()=>setView(location.hash.slice(1)));
$('weight-guide').innerHTML=LEVELS.map(l=>`<span class="severity-badge" style="${levelStyle(l)}">${LABELS[l]} −${WEIGHTS[l]}점</span>`).join('');
const mobileNav=document.createElement('nav');mobileNav.className='mobile-nav';mobileNav.setAttribute('aria-label','모바일 메뉴');mobileNav.innerHTML=Object.entries(views).map(([v,[label]])=>`<button class="mobile-nav-button" data-view="${v}">${label}</button>`).join('');document.querySelector('.context-bar').after(mobileNav);
renderDrafts();setMode('manual');render();setView(location.hash.slice(1)||'dashboard',false);hydrate();
